                if(!policy.valid() || module->flags != 1u || module->words != ::std::array<::std::uint64_t,8u>{
                    policy.revision,policy.cli_mode,policy.disabled,policy.controlled,0u,0u,0u,0u})
                { return fail(preparation_status::feature_mismatch); }
